column2:
flowchart TB
    Start(["เริ่มการขอใช้ตราประทับ"]) --> Requester{"ผู้ยื่นคำขอ"}
    Requester -- บุคลากรภายใน KMUTT --> KMUTTType{"ขอในนาม?"}
    KMUTTType -- หน่วยงาน --> DeptApprove["หัวหน้างานอนุมัติ"]
    KMUTTType -- โครงการ --> VP_Decision@{ label: "<span style=\"background-color:\">BPUU Staff ตรวจสอบและ</span>พิจารณาการขอใช้ตราประทับ" }
    DeptApprove --> VP_Decision
    Requester -- หน่วยงานในกำกับ --> VP_Decision
    Requester -- นักศึกษา --> VP_Decision
    VP_Decision -- มีค่าใช้จ่าย --> MgrSign2["BPUU Manager Approve"]
    MgrSign2 --> SendResult@{ label: "BPUU Staff ส่งคู่มือ และ รหัสตราประทับ และ รายละเอียดการใช้งานตราประทับ<span style=\"background-color:\">ให้ผู้ขอ</span><br>" }
    SendResult --> End(["จบกระบวนการ"])
    VP_Decision -- ยกเว้นค่าใช้จ่าย --> n1["BPUU Manager Approve"]
    n1 --> n2@{ label: "<span style=\"background-color:\">รองอธิการบดีฝ่ายการเงิน Approve</span>" }
    n2 --> SendResult
    VP_Decision -- ขอเอกสารเพิ่มเติม เช่นเอกสารโครงการ --> Requester

    VP_Decision@{ shape: diamond}
    SendResult@{ shape: rect}
    n2@{ shape: rect}
    style Start fill:#f9f,stroke:#333
    style VP_Decision fill:#fff4dd,stroke:#d4a017
    style MgrSign2 fill:#FFE0B2
    style SendResult fill:#d4edda,stroke:#28a745
    style n1 fill:#FFE0B2
    style n2 fill:#BBDEFB
    linkStyle 13 stroke:#D50000,fill:none
